import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;
  const group = new Group();

  // Create active animations roster for cleanup
  const activeTimelines = [];

  // --- STAGE BACKDROP (Designed-for-dark, vertical gradient) ---
  const backdropGeo = new PlaneGeometry(8, 6.5);
  const backdropMat = new MeshBasicNodeMaterial();

  // TSL: Engineered gradient from '#0b0b10' (bottom) to '#16161d' (top)
  const colorBottom = vec3(0.043, 0.043, 0.063); // #0b0b10
  const colorTop = vec3(0.086, 0.086, 0.114);    // #16161d
  backdropMat.colorNode = mix(colorBottom, colorTop, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- HERO ISOLATED IMAGE PLANE ---
  const imageWidth = 3.2;
  const imageHeight = 2.0;
  const imageGeo = new PlaneGeometry(imageWidth, imageHeight);
  const imageMat = new MeshBasicNodeMaterial({ 
    transparent: true,
    opacity: 0 // Will fade in
  });

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0.3, -0.2);
  group.add(imageMesh);

  // Load the texture safely
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((texture) => {
        imageMat.map = texture;
        imageMat.needsUpdate = true;
      })
      .catch((err) => console.warn('Failed to load image texture:', err));
  }

  // --- SUBHEAD TEXT ---
  // Default fallback copy if visualSpec contains none
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textContent = textItems[0]?.text ?? "Atelier Noir — precise · luxury · technical";

  const textElement = ctx.fontAtlas.createText(textContent, {
    fontSize: 24, // Sized cleanly for subhead role
    color: '#e8ecf2', // Paper
    align: 'center'
  });

  // Center-bottom aligned below the isolated image
  textElement.position.set(0, -0.9, 0.1);
  textElement.scale.setScalar(0.012); // Fit cleanly within context boundaries
  group.add(textElement);

  // --- ENTRANCE ANIMATION (GSAP Rise-in & Settle) ---
  // Ensure elements start in clean, offset states
  imageMesh.position.y += 0.15;
  textElement.position.y -= 0.1;
  textElement.scale.setScalar(0.001);

  const entranceTl = gsap.timeline({ defaults: { ease: 'power3.out' } });

  entranceTl.to(imageMat, {
    opacity: 1,
    duration: 1.2
  }, 0);

  entranceTl.to(imageMesh.position, {
    y: 0.3,
    duration: 1.4,
    ease: 'power4.out'
  }, 0);

  entranceTl.to(textElement.scale, {
    x: 0.012,
    y: 0.012,
    z: 0.012,
    duration: 1.0,
    ease: 'back.out(1.4)'
  }, 0.2);

  entranceTl.to(textElement.position, {
    y: -0.9,
    duration: 1.0
  }, 0.2);

  activeTimelines.push(entranceTl);

  // --- CLEANUP ---
  group.userData.cleanup = function() {
    activeTimelines.forEach((tl) => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    imageGeo.dispose();
    imageMat.dispose();
  };

  return group;
}
